"""Units of measure and conversion to grams."""
from fractions import Fraction
SPOON_ALIASES = {'teaspoon': 'tsp', 'teaspoons': 'tsp', 'tablespoon': 'tbsp', 'tablespoons': 'tbsp'}
VOLUME_ALIASES = {'cups': 'cup', 'liter': 'l', 'liters': 'l', 'litre': 'l'}
MASS_ALIASES = {'gram': 'g', 'grams': 'g', 'ounce': 'oz', 'ounces': 'oz'}
POUND_ALIASES = {'pound': 'lb', 'pounds': 'lb', 'lbs': 'lb'}
ALIASES = {**SPOON_ALIASES, **VOLUME_ALIASES, **MASS_ALIASES, **POUND_ALIASES}
VOLUME_ML = {'tsp': 5, 'tbsp': 15, 'cup': 240, 'ml': 1, 'l': 1000}
MASS_G = {'g': Fraction(1), 'kg': Fraction(1000), 'oz': Fraction('28.35'), 'lb': Fraction('453.6')}
DRY_DENSITY = [('flour', '0.53'), ('oats', '0.41'), ('rice', '0.85'), ('salt', '1.2'), ('sugar', '0.85')]
WET_DENSITY = [('butter', '0.96'), ('honey', '1.42'), ('milk', '1.03'), ('oil', '0.92'), ('water', '1')]
DENSITY = sorted(DRY_DENSITY + WET_DENSITY)
EACH_FRUIT = [('apple', 180), ('banana', 120), ('tomato', 120)]
EACH_OTHER = [('egg', 50), ('garlic', 5), ('onion', 110)]
EACH_GRAMS = sorted(EACH_FRUIT + EACH_OTHER)

def normalize_unit(word):
    """Look up a unit word: its standard short name and whether it measures a volume or a mass.

    The word is lower-cased, then mapped through ALIASES (teaspoon(s) -> tsp, tablespoon(s) -> tbsp, cups -> cup,
    gram(s) -> g, ounce(s) -> oz, pound(s)/lbs -> lb, liter(s)/litre -> l). The result is a volume unit when it is
    a key of VOLUME_ML (tsp, tbsp, cup, ml, l) and a mass unit when it is a key of MASS_G (g, kg, oz, lb).

    Returns a dict {"unit": str, "kind": "volume" or "mass"}, e.g. "Cups" -> {"unit": "cup", "kind": "volume"},
    or None when the word is not a unit.

    Valid inputs: word is a non-empty str of letters.
    """
    low = word.lower()
    low = ALIASES.get(low, low)
    if low in VOLUME_ML:
        return {'unit': low, 'kind': 'volume'}
    if low in MASS_G:
        return {'unit': low, 'kind': 'mass'}
    return None

def to_grams(item):
    """The weight in grams of an ingredient item.

    Mass units use MASS_G (g 1, kg 1000, oz 28.35, lb 453.6 grams). Volume units use VOLUME_ML (tsp 5, tbsp 15,
    cup 240, ml 1, l 1000 millilitres) times the food's density in g/ml from DENSITY (flour 0.53, sugar 0.85,
    butter 0.96, milk 1.03, water 1, oil 0.92, rice 0.85, salt 1.2, honey 1.42, oats 0.41). The unit "each" uses
    the piece weight from EACH_GRAMS (egg 50, onion 110, garlic 5, apple 180, banana 120, tomato 120 grams per
    piece). The exact product is rounded with round(float(grams), 1).

    DENSITY and EACH_GRAMS are lists of (food, value) pairs sorted by food: DENSITY holds (food, g/ml as a decimal
    str), EACH_GRAMS holds (food, int grams per piece).

    Returns a float. Raises ValueError when the weight cannot be known (a volume of a food without a density, or
    "each" of a food without a piece weight).

    Valid inputs: item is a dict {"amount": (numerator, denominator), "unit": str, "food": str} with the amount
    as amounts.parse_amount returns, the unit "each" or a "unit" of normalize_unit, and the food a non-empty
    lower-case str.
    """
    qty = Fraction(item['amount'][0], item['amount'][1])
    unit, food = (item['unit'], item['food'])
    density = dict(DENSITY)
    each = dict(EACH_GRAMS)
    if unit in MASS_G:
        grams = qty * MASS_G[unit]
    elif unit in VOLUME_ML:
        if food not in density:
            raise ValueError(f'no density for {food}')
        grams = qty * VOLUME_ML[unit] * Fraction(density[food])
    else:
        if food not in each:
            raise ValueError(f'no piece weight for {food}')
        grams = qty * each[food]
    return round(float(grams), 1)

