"""Kitchen units: every unit belongs to a base unit ("ml", "g" or "each") with a whole-number factor."""
from fractions_math import multiply_fractions
VOLUME = {'tsp': ('ml', 5), 'tbsp': ('ml', 15), 'cup': ('ml', 240), 'ml': ('ml', 1), 'l': ('ml', 1000)}
WEIGHT = {'g': ('g', 1), 'kg': ('g', 1000), 'oz': ('g', 28), 'lb': ('g', 448)}
COUNT = {'each': ('each', 1), 'dozen': ('each', 12)}
UNITS = {**VOLUME, **WEIGHT, **COUNT}
DISPLAY = {'ml': ['cup', 'tbsp', 'tsp'], 'g': ['kg', 'g'], 'each': ['each']}

def to_base(q, unit):
    """Convert the amount q of `unit` into its base unit, using UNITS.

    UNITS gives (base, factor): tsp 5 ml, tbsp 15 ml, cup 240 ml, ml 1, l 1000 ml; g 1, kg 1000 g, oz 28 g, lb 448 g;
    each 1, dozen 12 each. The base amount is q * factor.

    Returns a tuple (base unit str, (n, d) amount in lowest terms).

    Valid inputs: q is an (n, d) tuple in lowest terms with n >= 0, d > 0; unit is a key of UNITS.
    """
    base, factor = UNITS[unit]
    return (base, scale_fraction(q, factor, 1))

def display_unit(base, amount):
    """Choose the unit to show a base amount in, and the amount in that unit.

    DISPLAY lists the candidate units of each base from largest to smallest: ml: cup, tbsp, tsp; g: kg, g;
    each: each. The chosen unit is the first one in which the amount is at least 1 (amount / factor >= 1); when there
    is none, the last (smallest) one.

    Returns a tuple (unit, (n, d) amount in that unit, in lowest terms).

    Valid inputs: base is "ml", "g" or "each"; amount is an (n, d) tuple in lowest terms with n >= 0, d > 0.
    """
    choices = DISPLAY[base]
    for unit in choices:
        factor = UNITS[unit][1]
        if amount[0] >= factor * amount[1]:
            return (unit, multiply_fractions(amount, (1, factor)))
    last = choices[-1]
    return (last, multiply_fractions(amount, (1, UNITS[last][1])))

