"""Deciding matches and playing one round of the bracket."""
from elo import rate_match

def match_winner(a, b, ratings, seeds):
    """Who wins the match between slots a and b.

    A player facing a bye (None) wins without playing. Otherwise the player with the higher current rating wins; when
    the ratings are equal, the player with the smaller seed number wins.

    Returns a tuple (winner, loser); loser is None for a bye.

    Valid inputs: a and b are names or None, not both None; ratings is a dict {name: float} and seeds a dict
    {name: int}, both with an entry for every name given.
    """
    if b is None:
        return (a, None)
    if a is None:
        return (b, None)
    if ratings[a] > ratings[b]:
        return (a, b)
    if ratings[b] > ratings[a]:
        return (b, a)
    if seeds[a] < seeds[b]:
        return (a, b)
    return (b, a)

def play_round(slots, ratings, seeds):
    """Play one round: slots 0 and 1 meet, then slots 2 and 3, and so on.

    Each match is decided by match_winner with the ratings as they are at the start of the match; matches are
    played top to bottom, and after each real match (not a bye) both players' ratings are replaced by
    elo.rate_match(winner rating, loser rating). The input ratings dict is not changed.

    Returns a tuple (next_slots, new_ratings, results): next_slots is the list of winners in match order,
    new_ratings is a new dict {name: float} for every name in ratings, results is a list of (winner, loser or None)
    tuples in match order.

    Valid inputs: slots is a list of even length >= 2 of names or None, with no two None in the same match;
    ratings and seeds are as match_winner accepts.
    """
    new_ratings = dict(ratings)
    winners = []
    results = []
    for i in range(0, len(slots), 2):
        winner, loser = match_winner(slots[i], slots[i + 1], new_ratings, seeds)
        if loser is not None:
            pair = rate_match(new_ratings[winner], new_ratings[loser])
            new_ratings[winner] = pair[0]
            new_ratings[loser] = pair[1]
        winners.append(winner)
        results.append((winner, loser))
    return (winners, new_ratings, results)

