"""Daily summaries of cleaned hourly readings."""

def daily_summary(readings):
    """One summary per date that has at least one reading.

    For each date: tmin and tmax are the smallest and largest non-None temps, and tmean is round(sum / count) of
    the non-None temps (Python round, halves to even), all in tenths; all three are None when the date has no
    non-None temp. rain is the sum of the non-None rain values (0 when there are none). count is the number of
    non-None temps.

    Returns a dict {date: (tmin, tmax, tmean, rain, count)}.

    Valid inputs: readings is a list of dicts as quality.clean_readings returns.
    """
    groups = {}
    for reading in readings:
        groups.setdefault(reading['date'], []).append(reading)
    summary = {}
    for date in sorted(groups):
        temps = [r['temp'] for r in groups[date] if r['temp'] is not None]
        rain = 0
        for r in groups[date]:
            if r['rain'] is not None:
                rain += r['rain']
        if temps:
            mean = round(sum(temps) / len(temps))
            summary[date] = (min(temps), max(temps), mean, rain, len(temps))
        else:
            summary[date] = (None, None, None, rain, 0)
    return summary

