"""Reading hourly weather-station log lines. Values are kept as ints in tenths (12.5 C -> 125)."""
KEYS = {'T': 'temp', 'R': 'rain', 'W': 'wind'}

def parse_tenths(text):
    """Parse a decimal number with at most one digit after the point into an int number of tenths.

    "12.5" -> 125, "-3" -> -30, "-0.4" -> -4, "0" -> 0, "7.0" -> 70.

    Returns an int.

    Valid inputs: text is an optional "-", then 1 to 3 digits, then optionally "." and exactly one digit.
    """
    negative = text.startswith('-')
    if negative:
        text = text[1:]
    if '.' in text:
        whole, frac = text.split('.')
    else:
        whole, frac = (text, '0')
    value = int(whole) * 10 + int(frac)
    return -value if negative else value

def parse_line(line):
    """Parse one log line "YYYY-MM-DD HH:00 KEY=VALUE KEY=VALUE ...".

    Fields are separated by one or more spaces. Known keys are T (temperature, C), R (rain, mm) and W (wind, m/s);
    each value is parsed with parse_tenths. Unknown keys are ignored. A known key that does not appear gives None;
    if a key appears twice the last one counts.

    Returns a dict {"date": "YYYY-MM-DD", "hour": int 0-23, "temp": int or None, "rain": int or None,
    "wind": int or None}.

    Valid inputs: line is a str as described, with a real date, hour 00-23 and minutes "00"; values as
    parse_tenths accepts.
    """
    parts = line.split()
    record = {'date': parts[0], 'hour': int(parts[1][:2]), 'temp': None, 'rain': None, 'wind': None}
    for field in parts[2:]:
        key, value = field.split('=')
        if key in KEYS:
            record[KEYS[key]] = parse_tenths(value)
    return record

def parse_log(lines):
    """Parse a whole log into time order.

    Lines that are empty after stripping, or whose first non-space character is "#", are skipped. The others are
    parsed with parse_line. When two lines have the same date and hour, only the one that comes later in `lines`
    is kept. The result is sorted by (date, hour).

    Returns a list of dicts as parse_line returns.

    Valid inputs: lines is a list of 0 to 120 strs, each blank, a comment, or a line as parse_line accepts.
    """
    by_time = {}
    for line in lines:
        text = line.strip()
        if not text or text.startswith('#'):
            continue
        record = parse_line(text)
        by_time[record['date'], record['hour']] = record
    return [by_time[key] for key in sorted(by_time)]

